DROP VIEW PS_GPGB_RSLT_BAL
/
CREATE VIEW PS_GPGB_RSLT_BAL (EMPLID, CAL_RUN_ID, EMPL_RCD,
 GP_PAYGROUP, CAL_ID, RSLT_SEG_NUM, GPGB_ELE_ORDER, GPGB_PSLIP_DETAIL,
 GPGB_PSLIP_D_TXT, GPGB_PIN_NUM_CUR, GPGB_PSLIP_DESCR,
 GPGB_RSLT_VAL_CUR, GPGB_ADJ_VAL, GPGB_PIN_NUM_YTD, GPGB_RSLT_VAL_YTD,
 GPGB_ADJ_VAL_YTD) AS SELECT A.EMPLID , A.CAL_RUN_ID , A.EMPL_RCD ,
 A.GP_PAYGROUP , A.CAL_ID , A.RSLT_SEG_NUM , 0 , 0 , ' ' , A.PIN_NUM ,
 ' ' , ROUND(A.CALC_RSLT_VAL ,2) , ROUND(A.USER_ADJ_VAL ,2) , 0 , 0 ,
 0 FROM PS_GP_RSLT_ACUM A
/